-- Trigger to automatically resolve pending appeals when attendance record is updated to AWP/LWP
CREATE OR REPLACE FUNCTION public.tr_auto_resolve_attendance_appeal()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status IN ('absent_with_permission', 'lateness_with_permission') THEN
    UPDATE public.attendance_appeals
    SET status = 'approved',
        resolution_note = COALESCE(NEW.manual_comment, 'Automatically approved via manual roster update'),
        updated_at = now()
    WHERE user_id = NEW.user_id
      AND appeal_date = NEW.date
      AND status = 'pending';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS auto_resolve_appeal_on_record_update ON public.attendance_records;
CREATE TRIGGER auto_resolve_appeal_on_record_update
  AFTER INSERT OR UPDATE OF status ON public.attendance_records
  FOR EACH ROW
  EXECUTE FUNCTION public.tr_auto_resolve_attendance_appeal();

